const items = $input.all();
const output = [];

const webhookItems = $("Webhook").all();
const webhookItem = webhookItems[0];

const uploadedDocumentName =
  webhookItem?.binary?.file?.fileName ??
  webhookItem?.json?.fileName ??
  webhookItem?.json?.filename ??
  webhookItem?.json?.name ??
  "documento.pdf";

function chunkText(text, maxLength = 1200, overlap = 200) {
  const cleaned = String(text ?? "")
    .replace(/\s+/g, " ")
    .trim();

  const chunks = [];

  let start = 0;

  while (start < cleaned.length) {
    const end = Math.min(start + maxLength, cleaned.length);
    const chunk = cleaned.slice(start, end).trim();

    if (chunk.length > 0) {
      chunks.push(chunk);
    }

    start += maxLength - overlap;
  }

  return chunks;
}

for (const item of items) {
  const json = item.json ?? {};

  const text =
    json.text ??
    json.data ??
    json.content ??
    json.extractedText ??
    "";

  if (!String(text).trim()) {
    throw new Error("PDF sem texto extraivel. Use um PDF com texto selecionavel; OCR nao esta implementado.");
  }
  const chunks = chunkText(text);

  chunks.forEach((content, index) => {
    output.push({
      json: {
        documentName: uploadedDocumentName,
        pageNumber: null,
        chunkIndex: index,
        content,
      },
    });
  });
}

return output;

const items = $input.all();
const originalItems = $("Divide chunks").all();

return items.map((item, index) => {
  const embeddingArray = item.json.data?.[0]?.embedding;

  if (!embeddingArray) {
    throw new Error("Embedding não encontrado na resposta da OpenAI.");
  }

  const originalItem = originalItems[index]?.json;

  if (!originalItem) {
    throw new Error(`Item original não encontrado no índice ${index}.`);
  }

  return {
    json: {
      document_name:
        originalItem.documentName ??
        originalItem.document_name ??
        "documento.pdf",

      page_number:
        originalItem.pageNumber ??
        originalItem.page_number ??
        null,

      content:
        originalItem.content,

      embedding: `[${embeddingArray.join(",")}]`,
    },
  };
});
